fn merge_schema_metadata(
    op: &str,
    left: &DataContract,
    right: &DataContract,
) -> Result<Metadata> {
    let mut sources = [
        left.schema.metadata().clone(),
        right.schema.metadata().clone(),
    ];
    for source in &mut sources {
        source.remove(plenora_core::contract::arrow_schema::PRIMARY_GEOMETRY_KEY);
    }
    plenora_core::contract::geometry_metadata_policy::merge_schema(&[&sources[0], &sources[1]])
        .map_err(|error| PlenoraError::InvalidPlan(format!("{op}: {error}")))
}

fn analyze_diagnostics(
    op: &str,
    input: &DataContract,
    geometry: &GeometryColumnContract,
    allocator: &mut plenora_core::contract::FieldAllocator,
) -> Result<DataContract> {
    let mut fields = output_fields(input);
    let position = fields
        .iter()
        .position(|field| field.name() == &geometry.name)
        .ok_or_else(|| {
            PlenoraError::Schema(format!(
                "colonna geometria `{}` assente dallo schema",
                geometry.name
            ))
        })?;
    for (name, _) in &DIAGNOSTIC_COLUMNS {
        if fields
            .iter()
            .enumerate()
            .any(|(index, field)| index != position && field.name() == name)
        {
            return Err(PlenoraError::Schema(format!(
                "{op}: la colonna diagnostica `{name}` esiste gia' nello schema"
            )));
        }
    }
    // Tipo, conteggio e i tre flag ci sono per ogni geometria presente;
    // `validity_reason` manca per una geometria valida, i limiti per una
    // vuota.
    let diagnostic_fields: Vec<Field> = DIAGNOSTIC_COLUMNS
        .iter()
        .map(|(name, data_type)| {
            let sempre_presente = matches!(
                *name,
                "geometry_type" | "coordinate_count" | "is_empty" | "is_finite" | "is_valid"
            );
            Field::new(
                *name,
                data_type.clone(),
                geometry.nullable || !sempre_presente,
            )
        })
        .collect();
    fields
        .splice(position..=position, diagnostic_fields)
        .for_each(drop);
    let mut properties = input.properties.clone();
    if properties
        .sorted_by
        .as_ref()
        .and_then(|p| p.value())
        .is_some_and(|order| order.keys.contains(&geometry.field_id))
    {
        properties.sorted_by = None;
    }
    let mut origins = input.field_origins();
    origins.splice(
        position..=position,
        std::iter::repeat_n(FieldOrigin::New, DIAGNOSTIC_COLUMNS.len()),
    );
    input.rebuild(
        Arc::new(Schema::new_with_metadata(
            fields,
            input.schema.metadata().clone(),
        )),
        origins,
        input
            .geometries
            .iter()
            .filter(|g| g.field_id != geometry.field_id)
            .cloned()
            .collect(),
        input.active_geometry.filter(|id| *id != geometry.field_id),
        properties,
        allocator,
    )
}

fn analyze_geometry_accessors(
    op: &str,
    input: &DataContract,
    geometry: &GeometryColumnContract,
    config: &Value,
    allocator: &mut plenora_core::contract::FieldAllocator,
) -> Result<DataContract> {
    let parsed: GeometryAccessorsConfig = parse_config(op, config)?;
    let mut selected: Vec<usize> = match &parsed.fields {
        None => (0..ACCESSOR_COLUMNS.len()).collect(),
        Some(fields) => {
            if fields.is_empty() {
                return Err(invalid_param(op, "fields", "non deve essere vuoto"));
            }
            let mut indexes: Vec<usize> = fields.iter().map(|field| field.column_index()).collect();
            indexes.sort_unstable();
            indexes.dedup();
            if indexes.len() != fields.len() {
                return Err(invalid_param(op, "fields", "campi duplicati"));
            }
            indexes
        }
    };
    selected.sort_unstable();
    let prefix = parsed.output_prefix.as_deref().unwrap_or("");
    let geometria_nullable = geometry.nullable;
    let mut fields = output_fields(input);
    for index in selected {
        let (name, data_type) = &ACCESSOR_COLUMNS[index];
        // `start_point` ed `end_point` sono null anche per una geometria
        // presente che non e' una linea aperta; gli altri solo dove la
        // geometria e' null.
        let nullable = geometria_nullable || matches!(*name, "start_point" | "end_point");
        let name = format!("{prefix}{name}");
        if !ensure_name(&name) {
            return Err(invalid_param(op, "output_prefix", "produce un nome vuoto"));
        }
        ensure_name_free(op, &fields, &name)?;
        fields.push(Field::new(name, data_type.clone(), nullable));
    }
    rebuild(input, fields, input.properties.clone(), allocator)
}

